# Ton app appelle son sidecar (port 3500) pour agir sur un systeme externe.
# "sms" est le metadata.name d'un composant de sortie (ex. bindings.twilio.sms).
# L'operation "create" demande l'envoi ; data et metadata dependent du systeme.

curl -X POST http://localhost:3500/v1.0/bindings/sms \
  -H "Content-Type: application/json" \
  -d '{
    "operation": "create",
    "data": { "message": "Votre commande est expediee" },
    "metadata": { "toNumber": "+33123456789" }
  }'
